-- Rights/ReBAC v1.0.0 -> v1.1.0 performance hardening
CREATE TABLE IF NOT EXISTS rights_graph_meta (id TINYINT UNSIGNED PRIMARY KEY, revision BIGINT UNSIGNED NOT NULL DEFAULT 1, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO rights_graph_meta(id,revision) VALUES(1,1);
CREATE TABLE IF NOT EXISTS rights_subject_closure (descendant_entity_id VARCHAR(255) NOT NULL, ancestor_entity_id VARCHAR(255) NOT NULL, depth SMALLINT UNSIGNED NOT NULL, PRIMARY KEY(descendant_entity_id,ancestor_entity_id), KEY idx_rights_subject_closure_ancestor(ancestor_entity_id,descendant_entity_id), CONSTRAINT fk_rights_sc_desc FOREIGN KEY(descendant_entity_id) REFERENCES rights_entities(entity_id) ON DELETE CASCADE, CONSTRAINT fk_rights_sc_anc FOREIGN KEY(ancestor_entity_id) REFERENCES rights_entities(entity_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS rights_object_closure (descendant_entity_id VARCHAR(255) NOT NULL, ancestor_entity_id VARCHAR(255) NOT NULL, depth SMALLINT UNSIGNED NOT NULL, PRIMARY KEY(descendant_entity_id,ancestor_entity_id), KEY idx_rights_object_closure_ancestor(ancestor_entity_id,descendant_entity_id), CONSTRAINT fk_rights_oc_desc FOREIGN KEY(descendant_entity_id) REFERENCES rights_entities(entity_id) ON DELETE CASCADE, CONSTRAINT fk_rights_oc_anc FOREIGN KEY(ancestor_entity_id) REFERENCES rights_entities(entity_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO rights_subject_closure SELECT entity_id,entity_id,0 FROM rights_entities WHERE status='active';
INSERT IGNORE INTO rights_object_closure SELECT entity_id,entity_id,0 FROM rights_entities WHERE status='active';
